let pointingAt = 50;

let iter = 0;

let steps = [];
let reduced = 0;
$input.all().forEach((item) => {
  const value = Number(item.json.data.substring(1));
  const direction = item.json.data.charAt(0) === 'L' ? -1 : 1;

  pointingAt = (pointingAt + direction * value) % 100


  if (pointingAt === 0) {
    // steps = [...steps, {"zeroAt": iter}]
    reduced += 1;
  }

  iter += 1;
});

return [...steps, {"reduced":reduced}]

