let pointingAt = 50;

let iter = 0;

let steps = [];
let reduced = 0;
$input.all().forEach((item) => {
  let value = Number(item.json.data.substring(1));
  const direction = item.json.data.charAt(0);

  // Remove more than full rotations
  let zeroPassthroughs = 0;
  if (value > 100) {
    zeroPassthroughs += Math.floor(value / 100)
    value -= 100 * zeroPassthroughs
  }

  let previouslyPointingAt = pointingAt;
  pointingAt += (direction === "L") ? value * -1  : value

  while (pointingAt > 99) {
    pointingAt -= 100;
    if (pointingAt != 0 && previouslyPointingAt != 0) zeroPassthroughs += 1;
  }

  while (pointingAt < 0) {
    pointingAt += 100;
    if (pointingAt != 0 && previouslyPointingAt != 0) zeroPassthroughs += 1;    
  }

  if (pointingAt === 0) reduced += 1;
  reduced += zeroPassthroughs;

  // steps = [...steps, { iter, pointingAt, previouslyPointingAt, zeroPassthroughs }]

  iter += 1;
});

return [...steps, {"reduced":reduced}]

